"""
    Given an array and an item, this function traverses the array to locate
    the item.
    Parameters: array, item
    Returns: index if item is found, -1 if the item is not found
    """
def linear_search(array: Any, item: Any) -> object {
    for i in range(len(array)) {
        if (array[i] == item) {
            return i;
        }
    }
    return -1;
}

"""
    This function finds and returns the prime factorization
    of a whole number (excluding zero) via the reiterative division
    method.

    Example of usage:
      getPrimeFactors = myfuncPrimeFactors( 716 )
      print(getPrimeFactors)
    """
def myfuncPrimeFactors(n: Any) -> object {
    i = 2;
    factors = [];
    while (n != 1) {
        if ((n % i) == 0) {
            factors = factors + [i];
            n = n // i;
        } else {
            i = i + 1;
        }
    }
    return factors;
}

"""Returns the text in the given ParagraphElement.

        Args:
            element: a ParagraphElement from a Google Doc.
    """
def read_paragraph_element(element: Any) -> object {
    text_run = element.get('textRun');
    if not text_run {
        return '';
    }
    if (
        text_run.get('textStyle', {}).get('weightedFontFamily', {}).get(
            'fontFamily', ''
        )
        == 'Consolas'
    ) {
        return text_run.get('content');
    } else {
        return '';
    }
}

