def getTemperature(U_code: Any, y_helium: Any, ElectronAbundance: Any) -> object {
    U_cgs = U_code * 10000000000.0;
    gamma = 5 / 3.0;
    kB = 1.38e-16;
    m_proton = 1.67e-24;
    mu = (1.0 + (4 * y_helium)) / (1 + y_helium + ElectronAbundance);
    mean_molecular_weight = mu * m_proton;
    return ((mean_molecular_weight * (gamma - 1) * U_cgs) / kB);
}

""" Compile L' array (Gusfield theorem 2.2.2) using p and N array.
        L'[i] = largest index j less than n such that N[j] = |P[i:]| """
def big_l_prime_array(p: Any, n: Any) -> object {
    lp = [0] * len(p);
    for j in range((len(p) - 1)) {
        i = len(p) - n[j];
        if (i < len(p)) {
            lp[i] = j + 1;
        }
    }
    return lp;
}

